import { useEffect, useState } from 'react';
import { firstMeaning, ttsLocaleOf, type LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { cx } from '@/lib/cx.js';
import { platform } from '@/lib/platform/index.js';
import { t } from '@/i18n/index.js';
import type { CardOption, SessionCard } from '../build.js';
import styles from './Card.module.css';

interface ChoiceCardProps {
  card: SessionCard;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  outcome: 'correct' | 'wrong' | undefined;
  autoSpeak: boolean;
  onChoose: (option: CardOption) => void;
  alt: boolean;
}

/**
 * Multiple choice and cloze. The prompt sits in its own card, the four
 * options below it are numbered so the keys 1–4 pick them, and the right
 * answer is marked as soon as one is chosen.
 */
export function ChoiceCard({
  card,
  targetLang,
  meaningLang,
  outcome,
  autoSpeak,
  onChoose,
  alt,
}: ChoiceCardProps): React.JSX.Element {
  const [picked, setPicked] = useState<string | undefined>(undefined);
  const isCloze = card.type === 'cloze';
  const expected = isCloze ? card.clozeAnswer : card.word.headword;
  const settled = picked !== undefined || outcome !== undefined;

  // Auto-pronounce reads the prompt, which for a choice card is the meaning.
  useEffect(() => {
    if (autoSpeak && !isCloze) {
      platform.tts.speak(firstMeaning(card.word), ttsLocaleOf(meaningLang));
    }
  }, [autoSpeak, isCloze, card.word, meaningLang]);

  const choose = (option: CardOption): void => {
    if (settled) return;
    setPicked(option.label);
    onChoose(option);
  };

  const [before, after] = (card.clozeSentence ?? '').split('_____');

  return (
    <div className={cx(styles.stack, alt && styles.stackAlt)}>
      <div className={styles.promptCard}>
        {isCloze ? (
          <>
            <div className={styles.cloze}>
              <Bilingual lang={targetLang}>
                <>
                  {before}
                  <span className={styles.blank}>{settled ? expected : '?'}</span>
                  {after}
                </>
              </Bilingual>
            </div>
            {card.word.meanings?.[0]?.examples?.[0]?.translation !== undefined && (
              <div className={styles.clozeTranslation}>
                <Bilingual lang={meaningLang}>{card.word.meanings[0].examples[0].translation}</Bilingual>
              </div>
            )}
          </>
        ) : (
          <>
            <div className={styles.choicePrompt}>
              <Bilingual lang={meaningLang}>{firstMeaning(card.word)}</Bilingual>
            </div>
            {card.word.meanings?.[0]?.gloss !== undefined && (
              <div className={styles.choiceGloss}>
                <Bilingual lang={targetLang}>{card.word.meanings[0].gloss}</Bilingual>
              </div>
            )}
          </>
        )}
      </div>

      <div className={styles.options} role="group" aria-label={t('session.pickAnswer')}>
        {(card.options ?? []).map((option, index) => {
          const correct = option.label === expected;
          const chosen = option.label === picked;
          const show = settled && (correct || chosen);
          return (
            <button
              key={`${option.wordId}-${option.label}`}
              type="button"
              className={cx(
                styles.option,
                show && correct && styles.optionCorrect,
                show && !correct && styles.optionWrong,
              )}
              disabled={settled}
              onClick={() => {
                choose(option);
              }}
            >
              <span className={styles.optionKey}>{index + 1}</span>
              {/* Always the target language: every option is a headword (or,
                  on a cloze, the word that fills the blank) — build.ts takes
                  them from `word.headword`. Tagged as the meaning language
                  they were given the wrong face, and in a Persian notebook
                  an English word was laid out right to left. */}
              <span className={styles.optionLabel}>
                <Bilingual lang={targetLang}>{option.label}</Bilingual>
              </span>
              <span className={styles.optionMark}>{show ? (correct ? '✓' : '✕') : ''}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}
