import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import type { Word } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { NoteSheet } from '@/components/ui/NoteSheet.js';
import { Toast } from '@/components/ui/Toast.js';
import { t } from '@/i18n/index.js';
import { localTimeZone } from '@/lib/format.js';
import { setProgressFlags } from '@/db/mutations.js';
import { syncSoon } from '@/sync/store.js';
import { SCHEDULE_FOCUS, settingsPath } from '@/features/settings/paths.js';
import styles from './LeechCard.module.css';

interface Slipping {
  word: Word;
  lapses: number;
}

/**
 * "Words that keep slipping" (SRS v2 leech prompt), in the session summary
 * after "Worth another look". A word lands here only when this session's
 * miss brought it to the notebook's threshold, and the learner decides what
 * to do: a note, its examples, a rest, or nothing. Lexpad never hides a
 * word by itself. Resting it is retiring it, which acts at once and offers
 * Undo, like every reversible thing in this app.
 */
export function LeechCard({
  words,
  firstTime = false,
}: {
  words: readonly Slipping[];
  /**
   * The first time a learner meets this card (the new learner's journey,
   * M10): one line saying it happens to everyone, and where to change when
   * Lexpad asks.
   */
  firstTime?: boolean;
}): React.JSX.Element | null {
  const navigate = useNavigate();
  const [dismissed, setDismissed] = useState<ReadonlySet<string>>(new Set());
  const [noteFor, setNoteFor] = useState<Word | undefined>(undefined);
  const [toast, setToast] = useState<{ message: string; undo?: () => void } | undefined>(undefined);
  const shown = words.filter((entry) => !dismissed.has(entry.word.id));

  const dismiss = (wordId: string): void => {
    setDismissed((previous) => new Set(previous).add(wordId));
  };

  return (
    <>
      {/* Polite: it arrives with the summary and should be read after it. */}
      <section className={styles.section} aria-live="polite">
        {shown.length > 0 && <h2 className={styles.title}>{t('leech.title')}</h2>}
        {shown.length > 0 && firstTime && <p className={styles.tip}>{t('tip.firstLeech')}</p>}
        {shown.map(({ word, lapses }) => (
          <div key={word.id} className={styles.card}>
            <p className={styles.body}>
              {/* The headword is isolated (FSI…PDI), so a right-to-left word
                  keeps the English sentence around it in order. */}
              {t('leech.body', { word: `\u2068${word.headword}\u2069`, count: lapses })}
            </p>
            <div className={styles.actions}>
              <button
                type="button"
                className={styles.action}
                onClick={() => {
                  setNoteFor(word);
                }}
              >
                {t('leech.addNote')}
              </button>
              <button
                type="button"
                className={styles.action}
                onClick={() => {
                  void navigate(`/words/${word.id}`);
                }}
              >
                {t('leech.examples')}
              </button>
              <button
                type="button"
                className={styles.action}
                onClick={() => {
                  const timeZone = localTimeZone();
                  // Undo waits for the rest to be written, so a quick tap
                  // can never land first and be overwritten by it.
                  const resting = setProgressFlags(word.id, { retired: true }, timeZone);
                  void resting.then(() => syncSoon());
                  dismiss(word.id);
                  setToast({
                    message: t('leech.rested', { word: word.headword }),
                    undo: () => {
                      void resting
                        .then(() => setProgressFlags(word.id, { retired: false }, timeZone))
                        .then(() => syncSoon());
                      setDismissed((previous) => {
                        const next = new Set(previous);
                        next.delete(word.id);
                        return next;
                      });
                    },
                  });
                }}
              >
                {t('leech.rest')}
              </button>
              <button
                type="button"
                className={styles.quiet}
                onClick={() => {
                  dismiss(word.id);
                }}
              >
                {t('leech.keep')}
              </button>
            </div>
          </div>
        ))}
        {shown.length > 0 && firstTime && (
          <Link to={`${settingsPath('schedule')}#${SCHEDULE_FOCUS.hardWords}`} className={styles.rule}>
            {t('leech.changeRule')}
            <Icon name="chevronRight" size={14} weight={2.2} className={styles.ruleGo} />
          </Link>
        )}
      </section>

      {noteFor !== undefined && (
        <NoteSheet
          initial={noteFor.progress?.memo ?? ''}
          headword={noteFor.headword}
          onSave={(memo) => {
            const word = noteFor;
            void setProgressFlags(word.id, { memo }, localTimeZone()).then(() => syncSoon());
            setNoteFor(undefined);
            dismiss(word.id);
            setToast({ message: t('leech.noteSaved') });
          }}
          onClose={() => {
            setNoteFor(undefined);
          }}
        />
      )}

      {toast !== undefined && (
        <Toast
          message={toast.message}
          onUndo={toast.undo}
          onDone={() => {
            setToast(undefined);
          }}
        />
      )}
    </>
  );
}
