import { useEffect } from 'react';
import { firstMeaning, ttsLocaleOf, type LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { platform } from '@/lib/platform/index.js';
import { useShowsKeys } from '@/lib/windowClass.js';
import type { SessionCard } from '../build.js';
import { Answer } from './Answer.js';
import { Speaker } from './Speaker.js';
import styles from './Card.module.css';

interface FlipCardProps {
  card: SessionCard;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  autoSpeak: boolean;
  /** Read the example sentence aloud once the card is turned over. */
  speakExamples: boolean;
  /** True once the learner has revealed the answer. Owned by the shell. */
  flipped: boolean;
  onFlip: () => void;
  onEditMemo?: (() => void) | undefined;
  /** Alternates the entrance animation between cards. */
  alt: boolean;
}

/**
 * Classic, reverse and audio cards. The front asks, a tap or the space bar
 * flips it, and the grades live in the session's action bar. Audio hides the
 * word behind a play button and speaks it instead.
 */
export function FlipCard({
  card,
  targetLang,
  meaningLang,
  autoSpeak,
  speakExamples,
  flipped,
  onFlip,
  onEditMemo,
  alt,
}: FlipCardProps): React.JSX.Element {
  const showsKeys = useShowsKeys();
  const isAudio = card.type === 'audio';
  const isReverse = card.type === 'reverse';
  const front = isReverse ? firstMeaning(card.word) : card.word.headword;

  // The audio deck speaks as soon as the card appears, and auto-pronounce
  // does the same when it is switched on.
  useEffect(() => {
    if ((isAudio || autoSpeak) && !isReverse) {
      platform.tts.speak(card.word.headword, ttsLocaleOf(targetLang));
    }
  }, [isAudio, isReverse, autoSpeak, targetLang, card.word.headword]);

  // "Also read example sentences": the answer side is where the example is
  // shown and where the card waits for a grade, so that is where it is read.
  // Typed and multiple-choice cards move on by themselves after a right
  // answer, which would cut the sentence off halfway.
  const example = card.word.meanings?.flatMap((sense) => sense.examples ?? [])[0]?.sentence;
  useEffect(() => {
    if (flipped && speakExamples && example !== undefined) {
      platform.tts.speak(example, ttsLocaleOf(targetLang));
    }
  }, [flipped, speakExamples, example, targetLang]);

  const speak = (): void => {
    platform.tts.speak(card.word.headword, ttsLocaleOf(targetLang));
  };

  return (
    <div
      className={cx(styles.face, alt && styles.faceAlt)}
      // Tapping the face flips it, a convenience for pointers. It is not a
      // button: the keyboard has Space and the Show answer button below, and
      // a button wrapping the speaker button would be a control inside a
      // control.
      onClick={flipped ? undefined : onFlip}
    >
      {flipped ? (
        <Answer word={card.word} targetLang={targetLang} meaningLang={meaningLang} onEditMemo={onEditMemo} />
      ) : (
        <>
          <div className={styles.front}>
            {isAudio ? (
              <>
                <button
                  type="button"
                  className={styles.audioButton}
                  aria-label={t('session.playAgain')}
                  onClick={(event) => {
                    event.stopPropagation();
                    speak();
                  }}
                >
                  <Icon name="speaker" size={36} weight={1.9} />
                </button>
                <div className={styles.audioHint}>{t('session.audioHint')}</div>
              </>
            ) : (
              <>
                <div className={cx(styles.prompt, sizeFor(front))} dir="auto">
                  <Bilingual lang={isReverse ? meaningLang : targetLang}>{front}</Bilingual>
                </div>
                {!isReverse && card.word.pronunciation !== undefined && card.word.pronunciation !== '' && (
                  <div className={styles.pron}>{card.word.pronunciation}</div>
                )}
                {!isReverse && <Speaker text={card.word.headword} lang={targetLang} variant="front" />}
              </>
            )}
          </div>
          {/* With a keyboard to hand, the keys the session already answers
              to; the tap and the swipe are a touch screen's words. */}
          <div className={styles.flipHint}>
            {showsKeys ? t('session.keysToFlip') : t('session.tapToFlip')}
          </div>
        </>
      )}
    </div>
  );
}

/** The prototype shrinks the prompt as it lengthens, so it always fits. */
function sizeFor(text: string): string | undefined {
  if (text.length > 46) return styles.promptSmall;
  if (text.length > 26) return styles.promptMedium;
  return styles.promptLarge;
}
